// Some portions generated by Co-Pilot
import React from "react";
import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { axe } from "vitest-axe";
import SupportUs from "../page";

describe("Support Us page", () => {
  it("renders correctly", () => {
    const { container } = render(<SupportUs />);
    expect(container.firstChild).toMatchSnapshot();
  });

  it("has no accessibility violations", async () => {
    const { container } = render(<SupportUs />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("preserves each way to contribute and all promotion destinations", () => {
    const { container } = render(<SupportUs />);
    const links = [
      { name: "How to contribute", href: "/contributing/" },
      { name: "Become a sustainer", href: "/sustainers" },
      { name: "Become a member", href: "/members" },
      { name: "Adopters page", href: "/adopters" },
      {
        name: "conference talk",
        href: "https://www.meetup.com/adoptium-summit-series/",
      },
      { name: "case study", href: "https://forms.gle/WyZeYW7SNXpVYpKHA" },
    ];
    for (const link of links)
      expect(screen.getByRole("link", { name: link.name })).toHaveAttribute(
        "href",
        link.href,
      );
    expect(
      screen.getByRole("link", { name: "How to contribute" }),
    ).not.toHaveAttribute("target");
    expect(
      screen
        .getAllByRole("link", { name: "Learn More" })
        .map((link) => link.getAttribute("href")),
    ).toEqual(["/news/", "/slack"]);
    expect(container.querySelector("a button")).not.toBeInTheDocument();
    expect(screen.getAllByRole("heading", { level: 1 })).toHaveLength(1);
  });
});
